css:
/* Angry Lizard 63 by mi-series — https://uiverse.io/mi-series/angry-lizard-63 */
.forgot-password {
  background-color: #E8EAE3;
  max-width: 450px;
  border-radius: 10px;
  padding: 20px;
  color: #000;
  box-shadow: 0px 87px 78px -39px rgba(0,0,0,0.4);
}

.header {
  text-align: center;
  margin-top: 0.75rem;
}

.forgot-password .title {
  font-size: 1.875rem;
  font-weight: 700;
  line-height: 1.25rem;
  color: rgba(0, 0, 0, 1);
}

.forgot-password .sub-title {
  margin-top: 0.4rem;
  font-size: 1rem;
  line-height: 1.5rem;
}

.reset-option {
  margin-top: 1rem;
  margin-bottom: 15px;
}

.reset-option label {
  cursor: pointer;
  overflow: hidden;
  border: 2px solid rgba(229, 231, 235, 1);
  border-radius: 0.375rem;
  background-color: #F7F7F7;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem .4rem;
  margin: 10px 0;
  transform: all .15s ease;
}

.reset-option label .reset-info {
  display: flex;
  flex-direction: column;
  margin-left: 10px;
}

.reset-title {
  font-size: 1.25rem;
  line-height: 1.75rem;
  font-weight: 600;
  color: rgba(0, 0, 0, 1);
}

.reset-sub-title {
  font-size: 0.875rem;
  line-height: 1.25rem;
}

.reset-option input:checked + label {
  border-color: #FA2742;
}

.send-btn {
  text-decoration: none;
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.375rem;
  background-color: #FA2742;
  padding: 1rem 3rem;
  font-weight: 600;
  color: #000;
  transform: all .15s ease;
}

.send-btn:hover {
  opacity: .9;
}

.reset-option input {
  display: none;
}

.resend {
  color: #FA2742;
  font-weight: 600;
}
